sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	var customerHistoryLoadedAt = api.state.customerHistoryLoadedAt;
  var lastRefreshedAt = api.data.record.lastRefreshed.timestamp;
  var rw_refreshRequested = api.data.customer_activity_lazy_load_settings_1.refreshRequested;
  var formLastRefreshedAt = lastRefreshedAt || 0;
  if(rw_refreshRequested > customerHistoryLoadedAt && rw_refreshRequested > formLastRefreshedAt){
    return rw_refreshRequested;
  }
  if(customerHistoryLoadedAt > formLastRefreshedAt){
    return new Date().valueOf();
  }
  return formLastRefreshedAt;
}
